function MillSailClothReinforcementStripMaker.init() MillSailClothReinforcementStripMaker.ironStock=12; MillSailClothReinforcementStripMaker.bronzeStock=10; MillSailClothReinforcementStripMaker.woodStock=14; MillSailClothReinforcementStripMaker.leatherStock=10; MillSailClothReinforcementStripMaker.silverStock=8; MillSailClothReinforcementStripMaker.goldStock=6; MillSailClothReinforcementStripMaker.jewelStock=4; MillSailClothReinforcementStripMaker.pearlStock=4; MillSailClothReinforcementStripMaker.productStock={}; MillSailClothReinforcementStripMaker.buildings={}; MillSailClothReinforcementStripMaker.maker=nil; MillSailClothReinforcementStripMaker.activeMaking={}; MillSailClothReinforcementStripMaker.totalProducts=0; MillSailClothReinforcementStripMaker.dayTimer=0; print("[MillSailClothReinforcementStripMaker] Royal Mill Sail Cloth Reinforcement Strip Maker System initialized (6 products, 4 buildings)") end
function MillSailClothReinforcementStripMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillSailClothReinforcementStripMaker.maker={name=n or ("Trakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trakar najet: %s (spretnost: %d)",MillSailClothReinforcementStripMaker.maker.name,s),"success") end; return true end
function MillSailClothReinforcementStripMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillSailClothReinforcementStripMaker.build(id) local ok,e=MillSailClothReinforcementStripMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillSailClothReinforcementStripMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillSailClothReinforcementStripMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillSailClothReinforcementStripMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillSailClothReinforcementStripMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillSailClothReinforcementStripMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillSailClothReinforcementStripMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillSailClothReinforcementStripMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillSailClothReinforcementStripMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillSailClothReinforcementStripMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillSailClothReinforcementStripMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillSailClothReinforcementStripMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillSailClothReinforcementStripMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillSailClothReinforcementStripMaker.buildings==0 then return false,"Potrebna trakna delavnica" end; if not MillSailClothReinforcementStripMaker.maker then return false,"Potreben trakar" end; return true end
function MillSailClothReinforcementStripMaker.make(pt,qty) qty=qty or 1; local ok,e=MillSailClothReinforcementStripMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillSailClothReinforcementStripMaker.ironStock=MillSailClothReinforcementStripMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillSailClothReinforcementStripMaker.bronzeStock=MillSailClothReinforcementStripMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillSailClothReinforcementStripMaker.woodStock=MillSailClothReinforcementStripMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillSailClothReinforcementStripMaker.leatherStock=MillSailClothReinforcementStripMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillSailClothReinforcementStripMaker.silverStock=MillSailClothReinforcementStripMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillSailClothReinforcementStripMaker.goldStock=MillSailClothReinforcementStripMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillSailClothReinforcementStripMaker.jewelStock=MillSailClothReinforcementStripMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillSailClothReinforcementStripMaker.pearlStock=MillSailClothReinforcementStripMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillSailClothReinforcementStripMaker.maker then t=math.max(1,t-math.floor(MillSailClothReinforcementStripMaker.maker.skill/13)) end; table.insert(MillSailClothReinforcementStripMaker.activeMaking,{id="millsailclothreinforcementstrip_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillSailClothReinforcementStripMaker.completeMaking(m) local q=1.0+(MillSailClothReinforcementStripMaker.getQualityBonus()/100); if MillSailClothReinforcementStripMaker.maker then q=q+(MillSailClothReinforcementStripMaker.maker.skill/140) end; q=math.min(2.5,q); MillSailClothReinforcementStripMaker.productStock[m.productType]=(MillSailClothReinforcementStripMaker.productStock[m.productType] or 0)+m.quantity; MillSailClothReinforcementStripMaker.totalProducts=MillSailClothReinforcementStripMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillSailClothReinforcementStripMaker.maker then MillSailClothReinforcementStripMaker.maker.itemsMade=MillSailClothReinforcementStripMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillSailClothReinforcementStripMaker.maker.skill=math.min(100,MillSailClothReinforcementStripMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trak izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millsailclothreinforcementstrip.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillSailClothReinforcementStripMaker.update(dt) if not _G.state then return end; MillSailClothReinforcementStripMaker.dayTimer=MillSailClothReinforcementStripMaker.dayTimer+dt; if MillSailClothReinforcementStripMaker.dayTimer>=30 then MillSailClothReinforcementStripMaker.dayTimer=0; for i=#MillSailClothReinforcementStripMaker.activeMaking,1,-1 do local m=MillSailClothReinforcementStripMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillSailClothReinforcementStripMaker.completeMaking(m); table.remove(MillSailClothReinforcementStripMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillSailClothReinforcementStripMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillSailClothReinforcementStripMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillSailClothReinforcementStripMaker.getStats() return {ironStock=MillSailClothReinforcementStripMaker.ironStock,bronzeStock=MillSailClothReinforcementStripMaker.bronzeStock,woodStock=MillSailClothReinforcementStripMaker.woodStock,leatherStock=MillSailClothReinforcementStripMaker.leatherStock,silverStock=MillSailClothReinforcementStripMaker.silverStock,goldStock=MillSailClothReinforcementStripMaker.goldStock,jewelStock=MillSailClothReinforcementStripMaker.jewelStock,pearlStock=MillSailClothReinforcementStripMaker.pearlStock,productStock=MillSailClothReinforcementStripMaker.productStock,numBuildings=#MillSailClothReinforcementStripMaker.buildings,hasMaker=MillSailClothReinforcementStripMaker.maker~=nil,makerName=MillSailClothReinforcementStripMaker.maker and MillSailClothReinforcementStripMaker.maker.name or "—",makerSkill=MillSailClothReinforcementStripMaker.maker and MillSailClothReinforcementStripMaker.maker.skill or 0,activeMaking=#MillSailClothReinforcementStripMaker.activeMaking,totalProducts=MillSailClothReinforcementStripMaker.totalProducts} end
